  ctrl_reg.error                         offset=AbsoluteStatic(0x00:6) size=Fixed(1bit) align=Unaligned repr=ValueConverted atomic=NonAtomic mutate=RewriteRequired
  ctrl_reg.<reserved0>                   offset=AbsoluteStatic(0x00:7) size=Fixed(25bit) align=Unaligned repr=ValueConverted atomic=NonAtomic

